static storage_dir_entry_t make_entry(const char *name, uint32_t size)
{
    storage_dir_entry_t e;
    memset(&e, 0, sizeof(e));
    strncpy(e.name, name, sizeof(e.name) - 1U);
    e.size_bytes = size;
    return e;
}

void test_empty_card_returns_zero_files_not_an_error(void)
{
    /* No dir entries set at all - simulates a freshly formatted card. */
    file_entry_t out[8];
    size_t count = 0xFFFFU;

    storage_result_t result = file_index_list(out, 8U, &count);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(0U, count);
}

void test_lists_valid_wav_files_correctly(void)
{
    storage_dir_entry_t raw[3] = {
        make_entry("FILE001.WAV", 1000U),
        make_entry("FILE002.WAV", 2000U),
        make_entry("FILE003.WAV", 3000U)
    };
    StoragePortFake_SetDirEntries(raw, 3U);

    file_entry_t out[8];
    size_t count = 0U;
    storage_result_t result = file_index_list(out, 8U, &count);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(3U, count);
    TEST_ASSERT_EQUAL_STRING("FILE001.WAV", out[0].name);
    TEST_ASSERT_EQUAL_UINT32(1000U, out[0].size_bytes);
    TEST_ASSERT_EQUAL_STRING("FILE003.WAV", out[2].name);
}

