void test_returned_names_are_always_null_terminated(void)
{
    storage_dir_entry_t raw[1];
    memset(&raw[0], 'A', sizeof(raw[0].name)); /* deliberately unterminated */
    raw[0].name[8] = '.';
    raw[0].name[9] = 'W';
    raw[0].name[10] = 'A';
    raw[0].name[11] = 'V';
    raw[0].name[12] = '\0';
    raw[0].size_bytes = 10U;
    StoragePortFake_SetDirEntries(raw, 1U);

    file_entry_t out[4];
    size_t count = 0U;
    file_index_list(out, 4U, &count);

    TEST_ASSERT_EQUAL_UINT32(1U, count);
    /* Must never hand the UI a string without a terminator. */
    TEST_ASSERT_EQUAL_UINT8('\0', out[0].name[sizeof(out[0].name) - 1U]);
    TEST_ASSERT_TRUE(strlen(out[0].name) < sizeof(out[0].name));
}

