/* ---------- multi-step: list then select, as the UI does ---------- */

void test_list_then_select_matches_the_ui_interaction(void)
{
    storage_dir_entry_t raw[4] = {
        make_entry("REC001.WAV", 1000U),
        make_entry("NOTES.TXT", 50U),
        make_entry("REC002.WAV", 2000U),
        make_entry("REC003.WAV", 3000U)
    };
    StoragePortFake_SetDirEntries(raw, 4U);

    /* 1. UI opens the FILE (SD) screen and asks for the list. */
    file_entry_t list[8];
    size_t count = 0U;
    TEST_ASSERT_EQUAL(STORAGE_OK, file_index_list(list, 8U, &count));
    TEST_ASSERT_EQUAL_UINT32(3U, count);

    /* 2. Encoder scrolls to the second visible item and the user taps it. */
    file_entry_t selected;
    TEST_ASSERT_EQUAL(STORAGE_OK, file_index_select(list, count, 1U, &selected));
    TEST_ASSERT_EQUAL_STRING("REC002.WAV", selected.name);
    TEST_ASSERT_EQUAL_UINT32(2000U, selected.size_bytes);

    /* 3. Scrolling one past the last item must be rejected, not wrapped
     *    into out-of-bounds memory. */
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, file_index_select(list, count, 3U, &selected));
}

void test_relisting_after_a_new_recording_shows_the_extra_file(void)
{
    storage_dir_entry_t before[2] = {
        make_entry("REC001.WAV", 1000U), make_entry("REC002.WAV", 2000U)
    };
    StoragePortFake_SetDirEntries(before, 2U);

    file_entry_t list[8];
    size_t count = 0U;
    file_index_list(list, 8U, &count);
    TEST_ASSERT_EQUAL_UINT32(2U, count);

    /* A new recording lands on the card. */
    storage_dir_entry_t after[3] = {
        make_entry("REC001.WAV", 1000U),
        make_entry("REC002.WAV", 2000U),
        make_entry("REC003.WAV", 3000U)
    };
    StoragePortFake_SetDirEntries(after, 3U);

    file_index_list(list, 8U, &count);
    TEST_ASSERT_EQUAL_UINT32(3U, count);
    TEST_ASSERT_EQUAL_STRING("REC003.WAV", list[2].name);
}

/* TEAM CODE (written by Brendon, integrator, 29 Oct 2026, best-ui): the file_index_list_newest tests below */
/* ---------- file_index_list_newest: the newest recordings, no empty ones ---------- */

#define TEN_SECOND_WAV_BYTES 640044U /* 44-byte header + 10 s of 32 kHz mono 16-bit */

/* Fill raw[] with count playable recordings REC00.WAV, REC01.WAV, ... in
 * directory (creation) order, as the toy names them. */
static void fill_recordings(storage_dir_entry_t *raw, size_t count)
{
    for (size_t i = 0U; i < count; i++)
    {
        char name[13] = "REC00.WAV";
        name[3] = (char)('0' + (i / 10U));
        name[4] = (char)('0' + (i % 10U));
        raw[i] = make_entry(name, TEN_SECOND_WAV_BYTES);
    }
}

void test_newest_keeps_the_last_sixteen_of_twenty_recordings(void)
{
    storage_dir_entry_t raw[20];
    fill_recordings(raw, 20U);
    StoragePortFake_SetDirEntries(raw, 20U);

    file_entry_t out[16];
    size_t count = 0U;
    storage_result_t result = file_index_list_newest(out, 16U, &count);

    /* REC00..REC03 drop out; the 5th entry comes first, the 20th last. */
    TEST_ASSERT_EQUAL(STORAGE_TRUNCATED, result);
    TEST_ASSERT_EQUAL_UINT32(16U, count);
    for (size_t i = 0U; i < 16U; i++)
    {
        TEST_ASSERT_EQUAL_STRING(raw[i + 4U].name, out[i].name);
        TEST_ASSERT_EQUAL_UINT32(TEN_SECOND_WAV_BYTES, out[i].size_bytes);
    }
    TEST_ASSERT_EQUAL_STRING("REC04.WAV", out[0].name);
    TEST_ASSERT_EQUAL_STRING("REC19.WAV", out[15].name);
}

void test_newest_exactly_sixteen_recordings_is_not_truncation(void)
{
    storage_dir_entry_t raw[16];
    fill_recordings(raw, 16U);
    StoragePortFake_SetDirEntries(raw, 16U);

    file_entry_t out[16];
    size_t count = 0U;
    storage_result_t result = file_index_list_newest(out, 16U, &count);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(16U, count);
    TEST_ASSERT_EQUAL_STRING("REC00.WAV", out[0].name);
    TEST_ASSERT_EQUAL_STRING("REC15.WAV", out[15].name);
}

void test_newest_a_17th_recording_shows_up_last(void)
{
    /* The card already holds 16 recordings: all of them are listed. */
    storage_dir_entry_t raw[17];
    fill_recordings(raw, 17U);
    StoragePortFake_SetDirEntries(raw, 16U);

    file_entry_t list[16];
    size_t count = 0U;
    TEST_ASSERT_EQUAL(STORAGE_OK, file_index_list_newest(list, 16U, &count));
    TEST_ASSERT_EQUAL_STRING("REC15.WAV", list[15].name);

    /* REC16.WAV is recorded and the card is listed again: the new file is
     * the last entry and the oldest one makes room for it. */
    StoragePortFake_SetDirEntries(raw, 17U);
    TEST_ASSERT_EQUAL(STORAGE_TRUNCATED, file_index_list_newest(list, 16U, &count));
    TEST_ASSERT_EQUAL_UINT32(16U, count);
    TEST_ASSERT_EQUAL_STRING("REC01.WAV", list[0].name);
    TEST_ASSERT_EQUAL_STRING("REC16.WAV", list[15].name);
}

