void test_newest_skips_recordings_with_no_samples(void)
{
    storage_dir_entry_t raw[5] = {
        make_entry("REC00.WAV", 0U),   /* card pulled mid-recording */
        make_entry("REC01.WAV", 43U),  /* shorter than a header */
        make_entry("REC02.WAV", 44U),  /* a header and no samples */
        make_entry("REC03.WAV", 45U),  /* one byte past the header */
        make_entry("REC04.WAV", TEN_SECOND_WAV_BYTES)
    };
    StoragePortFake_SetDirEntries(raw, 5U);

    file_entry_t out[8];
    size_t count = 0U;
    storage_result_t result = file_index_list_newest(out, 8U, &count);

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL_UINT32(2U, count);
    TEST_ASSERT_EQUAL_STRING("REC03.WAV", out[0].name);
    TEST_ASSERT_EQUAL_UINT32(45U, out[0].size_bytes);
    TEST_ASSERT_EQUAL_STRING("REC04.WAV", out[1].name);
}

