/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): the streaming scan (fi_scan_*) tests below */
/* ---------- fi_scan: windows over a root of any size ----------
 * Each test builds a fake root, runs a scan to the end and checks the
 * window (first, count, names), the total, the anchor position and the
 * last name. Files are named F000.WAV, F001.WAV, ... in card order. */

#define SCAN_GEN          7U     /* any list generation; a test that changes it says so */
#define SCAN_STEP_BUDGET  16U    /* entries per step while a recording or playback runs (Jack's budget) */
#define SCAN_MAX_STEPS    1000U  /* a scan that needs more steps than this is stuck: the test fails */

static storage_dir_entry_t s_root[STORAGE_FAKE_MAX_DIR_ENTRIES];

/* Make the fake root list hold count playable files <letter>000.WAV,
 * <letter>001.WAV, ... (the list the root iterator reads, not the fake card). */
static void put_numbered_files(char letter, size_t count)
{
    for (size_t i = 0U; i < count; i++)
    {
        char name[13];
        (void)snprintf(name, sizeof(name), "%c%03u.WAV", letter, (unsigned)i);
        s_root[i] = make_entry(name, TEN_SECOND_WAV_BYTES);
    }
    StoragePortFake_SetDirEntries(s_root, count);
}

/* The name <letter><i>.WAV, i in three digits, for comparing. One static
 * buffer: use the result before the next call. */
static const char *numbered_name(char letter, unsigned i)
{
    static char name[13];
    (void)snprintf(name, sizeof(name), "%c%03u.WAV", letter, i);
    return name;
}

/* Begin a scan and step it with the given budget until it is done. */
static void run_scan(fi_scan_t *s, uint16_t want, const char *anchor, bool count_only, uint32_t budget)
{
    fi_scan_begin(s, want, anchor, count_only, SCAN_GEN);
    for (uint32_t step = 0U; step < SCAN_MAX_STEPS; step++)
    {
        if (fi_scan_step(s, budget, SCAN_GEN))
        {
            return;
        }
    }
    TEST_FAIL_MESSAGE("the scan never finished");
}

void test_scan_counts_every_playable_file_in_the_root(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, 0U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_TRUE(fi_scan_done(&s));
    TEST_ASSERT_EQUAL(STORAGE_OK, s.result);
    TEST_ASSERT_EQUAL_UINT16(40U, s.total);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.last);
    TEST_ASSERT_FALSE(StoragePortFake_IsDirOpen());
}

void test_scan_window_is_centred_on_the_wanted_index(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, 20U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(12U, s.first);          /* 20 - 8 */
    TEST_ASSERT_EQUAL_UINT8(16U, s.count);
    TEST_ASSERT_EQUAL_STRING("F012.WAV", s.names[0]);
    TEST_ASSERT_EQUAL_STRING("F020.WAV", s.names[8]);
    TEST_ASSERT_EQUAL_STRING("F027.WAV", s.names[15]);
    TEST_ASSERT_EQUAL_UINT16(FI_INDEX_NONE, s.found);
}

void test_scan_window_at_the_start_begins_at_zero(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, 3U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(0U, s.first);
    TEST_ASSERT_EQUAL_UINT8(16U, s.count);
    TEST_ASSERT_EQUAL_STRING("F000.WAV", s.names[0]);
    TEST_ASSERT_EQUAL_STRING("F003.WAV", s.names[3]);
}

void test_scan_window_at_the_end_holds_the_last_sixteen(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, 39U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(24U, s.first);          /* 40 - 16 */
    TEST_ASSERT_EQUAL_UINT8(16U, s.count);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.names[15]);

    /* An index past the end (a list that got shorter) also ends there. */
    run_scan(&s, 50U, "", false, FI_NO_LIMIT);
    TEST_ASSERT_EQUAL_UINT16(24U, s.first);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.names[15]);
}

void test_scan_index_last_gives_the_last_entry(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, FI_INDEX_LAST, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(40U, s.total);
    TEST_ASSERT_EQUAL_UINT16(24U, s.first);
    TEST_ASSERT_EQUAL_UINT8(16U, s.count);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.names[s.count - 1U]);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.last);
}

