void test_scan_of_300_files_reaches_file_300(void)
{
    put_numbered_files('F', 300U);
    fi_scan_t s;
    run_scan(&s, 299U, "", false, SCAN_STEP_BUDGET);

    TEST_ASSERT_EQUAL_UINT16(300U, s.total);
    TEST_ASSERT_EQUAL_UINT16(284U, s.first);         /* 300 - 16 */
    TEST_ASSERT_EQUAL_STRING("F299.WAV", s.names[15]);
    TEST_ASSERT_EQUAL_STRING("F299.WAV", s.last);
}

void test_scan_of_256_files_counts_past_255(void)
{
    put_numbered_files('F', 256U);
    fi_scan_t s;
    run_scan(&s, 255U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(256U, s.total);         /* a uint8_t count would say 0 */
    TEST_ASSERT_EQUAL_STRING("F255.WAV", s.names[s.count - 1U]);
}

void test_scan_windows_for_0_1_16_17_255_256_and_300_files(void)
{
    static const uint16_t totals[] = { 0U, 1U, 16U, 17U, 255U, 256U, 300U };
    for (size_t t = 0U; t < (sizeof(totals) / sizeof(totals[0])); t++)
    {
        const uint16_t n = totals[t];
        const uint8_t window = (uint8_t)((n < FI_WINDOW) ? n : FI_WINDOW);
        const uint16_t last_first = (uint16_t)((n > FI_WINDOW) ? (n - FI_WINDOW) : 0U);
        put_numbered_files('F', n);
        fi_scan_t s;

        /* The window at index 0: the first files. */
        run_scan(&s, 0U, "", false, SCAN_STEP_BUDGET);
        TEST_ASSERT_EQUAL_UINT16(n, s.total);
        TEST_ASSERT_EQUAL_UINT16(0U, s.first);
        TEST_ASSERT_EQUAL_UINT8(window, s.count);
        if (n > 0U)
        {
            TEST_ASSERT_EQUAL_STRING("F000.WAV", s.names[0]);
        }

        /* The window at the end: the last files. */
        run_scan(&s, FI_INDEX_LAST, "", false, SCAN_STEP_BUDGET);
        TEST_ASSERT_EQUAL_UINT16(last_first, s.first);
        TEST_ASSERT_EQUAL_UINT8(window, s.count);
        if (n > 0U)
        {
            TEST_ASSERT_EQUAL_STRING(numbered_name('F', (unsigned)(n - 1U)), s.names[s.count - 1U]);
            TEST_ASSERT_EQUAL_STRING(numbered_name('F', (unsigned)(n - 1U)), s.last);
        }
        else
        {
            TEST_ASSERT_EQUAL_STRING("", s.last);
        }
    }
}

void test_scan_skips_non_wav_header_only_and_mac_files(void)
{
    storage_dir_entry_t raw[6] = {
        make_entry("A.WAV", 1000U),
        make_entry("README.TXT", 200U),
        make_entry("B.WAV", 44U),                    /* a bare 44-byte header: no samples */
        make_entry("_C~1.WAV", 1000U),               /* Mac metadata */
        make_entry("EMPTY.WAV", 0U),                 /* a card pull mid-recording */
        make_entry("d.wav", 1000U)                   /* any case */
    };
    StoragePortFake_SetDirEntries(raw, 6U);
    fi_scan_t s;
    run_scan(&s, 0U, "", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(2U, s.total);
    TEST_ASSERT_EQUAL_UINT8(2U, s.count);
    TEST_ASSERT_EQUAL_STRING("A.WAV", s.names[0]);
    TEST_ASSERT_EQUAL_STRING("d.wav", s.names[1]);
    TEST_ASSERT_EQUAL_STRING("d.wav", s.last);
}

void test_scan_in_steps_of_16_equals_one_unlimited_step(void)
{
    put_numbered_files('F', 300U);
    fi_scan_t stepped;
    fi_scan_t whole;
    run_scan(&stepped, 150U, "F201.WAV", false, SCAN_STEP_BUDGET);
    run_scan(&whole, 150U, "F201.WAV", false, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL(whole.result, stepped.result);
    TEST_ASSERT_EQUAL_UINT16(whole.total, stepped.total);
    TEST_ASSERT_EQUAL_UINT16(whole.found, stepped.found);
    TEST_ASSERT_EQUAL_UINT16(whole.first, stepped.first);
    TEST_ASSERT_EQUAL_UINT8(whole.count, stepped.count);
    TEST_ASSERT_EQUAL_MEMORY(whole.names, stepped.names, sizeof(whole.names));
    TEST_ASSERT_EQUAL_STRING(whole.last, stepped.last);
    TEST_ASSERT_EQUAL_UINT16(201U, stepped.found);
}

void test_scan_step_never_reads_more_than_its_budget(void)
{
    put_numbered_files('F', 300U);
    fi_scan_t s;
    fi_scan_begin(&s, FI_INDEX_LAST, "", false, SCAN_GEN);
    bool done = false;
    uint32_t steps = 0U;
    while (!done && steps < SCAN_MAX_STEPS)
    {
        const size_t before = StoragePortFake_GetDirNextCallCount();
        done = fi_scan_step(&s, SCAN_STEP_BUDGET, SCAN_GEN);
        const size_t read = StoragePortFake_GetDirNextCallCount() - before;
        TEST_ASSERT_TRUE(read <= SCAN_STEP_BUDGET);
        steps++;
    }
    TEST_ASSERT_TRUE(done);
    TEST_ASSERT_TRUE(steps > 2U);                    /* 300 entries cannot fit in two steps of 16 */
    TEST_ASSERT_EQUAL_STRING("F299.WAV", s.names[15]);
}

void test_scan_count_only_reads_one_pass_and_copies_no_names(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    run_scan(&s, 0U, "", true, FI_NO_LIMIT);

    TEST_ASSERT_EQUAL_UINT16(40U, s.total);
    TEST_ASSERT_EQUAL_UINT8(0U, s.count);
    TEST_ASSERT_EQUAL_STRING("F039.WAV", s.last);
    TEST_ASSERT_EQUAL_UINT32(41U, (uint32_t)StoragePortFake_GetDirNextCallCount());   /* 40 entries + the end */
}

void test_scan_abort_closes_the_root_and_the_next_step_starts_again(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;
    fi_scan_begin(&s, 0U, "F035.WAV", false, SCAN_GEN);
    TEST_ASSERT_FALSE(fi_scan_step(&s, SCAN_STEP_BUDGET, SCAN_GEN));
    TEST_ASSERT_TRUE(StoragePortFake_IsDirOpen());

    fi_scan_abort(&s);
    TEST_ASSERT_FALSE(StoragePortFake_IsDirOpen());
    TEST_ASSERT_FALSE(fi_scan_done(&s));

    /* The same question, asked again from the first entry. */
    while (!fi_scan_step(&s, SCAN_STEP_BUDGET, SCAN_GEN))
    {
    }
    TEST_ASSERT_EQUAL_UINT16(40U, s.total);
    TEST_ASSERT_EQUAL_UINT16(35U, s.found);
    TEST_ASSERT_EQUAL_STRING("F035.WAV", s.names[35U - s.first]);
}

void test_scan_of_an_unreadable_root_is_corrupt(void)
{
    put_numbered_files('F', 40U);
    fi_scan_t s;

    /* The root cannot be opened at all. */
    StoragePortFake_SetDirOpenResult(STORAGE_CORRUPT);
    run_scan(&s, 0U, "", false, FI_NO_LIMIT);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, s.result);
    TEST_ASSERT_EQUAL_UINT8(0U, s.count);

    /* The root fails part-way: the iterator is closed again. */
    StoragePortFake_SetDirOpenResult(STORAGE_OK);
    StoragePortFake_SetDirCorruptAt(5U);
    run_scan(&s, 0U, "", false, FI_NO_LIMIT);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, s.result);
    TEST_ASSERT_EQUAL_UINT8(0U, s.count);
    TEST_ASSERT_FALSE(StoragePortFake_IsDirOpen());
}

void test_scan_restarts_when_the_list_generation_changes(void)
{
    /* List A is on the card when the scan begins ... */
    put_numbered_files('A', 40U);
    fi_scan_t s;
    fi_scan_begin(&s, 0U, "", false, SCAN_GEN);
    TEST_ASSERT_FALSE(fi_scan_step(&s, SCAN_STEP_BUDGET, SCAN_GEN));

    /* ... then the root changes (a recording ended, a file was deleted) and
     * Jack raises the list generation. List B is shorter than the 16
     * entries of list A already read, so a scan that did not restart
     * would count 16 here. */
    put_numbered_files('B', 10U);
    bool done = false;
    for (uint32_t step = 0U; !done && step < SCAN_MAX_STEPS; step++)
    {
        done = fi_scan_step(&s, SCAN_STEP_BUDGET, SCAN_GEN + 1U);
    }

    /* Counted and copied from list B only. */
    TEST_ASSERT_TRUE(done);
    TEST_ASSERT_EQUAL_UINT16(SCAN_GEN + 1U, s.gen);
    TEST_ASSERT_EQUAL_UINT16(10U, s.total);
    TEST_ASSERT_EQUAL_UINT8(10U, s.count);
    TEST_ASSERT_EQUAL_STRING("B000.WAV", s.names[0]);
    TEST_ASSERT_EQUAL_STRING("B009.WAV", s.last);
}

